/* Murphy, inspiré de la photo de son propriétaire, porte un crapaud.
   Un clic sur [data-crapaud] déclenche une seule traversée de droite à gauche.
   Les huit poses et leur transparence sont intégrées au fichier. */
(function () {
  'use strict';
  if (window.__crapaudEgg) return;
  window.__crapaudEgg = true;

  var atlas = 'data:image/png;base64,';
  var style = document.createElement('style');
  style.textContent = [
    '.cx-wrap{position:fixed;left:0;bottom:1.5vh;z-index:2147483000;pointer-events:none;width:var(--cx-w);height:calc(var(--cx-w) * .50);will-change:transform;contain:layout style}',
    '.cx-murphy{position:absolute;left:11%;bottom:calc(var(--cx-w) * -.1404);width:78%;aspect-ratio:1;background-repeat:no-repeat;background-size:400% 200%;pointer-events:none}',
    '.cx-say{position:absolute;left:48%;top:0;transform:translate(-50%,-100%) scale(.8);opacity:0;transition:opacity .25s ease,transform .25s ease;white-space:nowrap;',
    "font:italic 600 clamp(14px,2.2vmin,22px)/1 'Cormorant Garamond',Georgia,serif;color:#f0d9a8;",
    'background:rgba(6,8,20,.88);border:1px solid rgba(232,193,122,.4);padding:.35em .75em;border-radius:999px}',
    '.cx-say.on{opacity:1;transform:translate(-50%,-100%) scale(1)}',
    '@media(prefers-reduced-motion:reduce){.cx-say{transition:none}}'
  ].join('');
  document.head.appendChild(style);

  var image = new Image();
  var ready = new Promise(function (resolve) {
    image.onload = function () { resolve(true); };
    image.onerror = function () { resolve(false); };
  });
  image.src = atlas;
  var running = false;
  var stop = null;

  async function start() {
    if (running) return;
    running = true;
    if (!await ready) { running = false; return; }

    var W = window.innerWidth, H = window.innerHeight;
    // Même règle de taille que le chat précédent, marges du dessin compensées.
    var w = Math.max(190, Math.min(420, Math.min(W, H) * .30));
    var dur = Math.max(5500, Math.min(10000, W * 4));
    var speed = (W + w) / (dur / 1000);
    var cycle = Math.max(.40, Math.min(.90, (.52 * w) / speed)) * 1000;
    var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var el = document.createElement('div');
    el.className = 'cx-wrap';
    el.setAttribute('aria-hidden', 'true');
    el.style.setProperty('--cx-w', w + 'px');
    var sprite = document.createElement('div');
    sprite.className = 'cx-murphy';
    sprite.style.backgroundImage = 'url("' + atlas + '")';
    var say = document.createElement('span');
    say.className = 'cx-say';
    say.textContent = 'croâ';
    el.append(sprite, say);
    document.body.appendChild(el);

    var raf = 0, began = null, finished = false;
    function finish() {
      if (finished) return;
      finished = true;
      cancelAnimationFrame(raf);
      el.remove();
      running = false;
      stop = null;
    }
    stop = finish;
    function tick(time) {
      if (began === null) began = time;
      var elapsed = time - began;
      if (elapsed >= (reduced ? 2200 : dur)) { finish(); return; }
      var frame = reduced ? 0 : Math.floor((elapsed % cycle) / cycle * 8);
      sprite.style.backgroundPosition = ((frame % 4) * 100 / 3) + '% ' + (Math.floor(frame / 4) * 100) + '%';
      var x = reduced ? W - w : W - (W + w) * elapsed / dur;
      el.style.transform = 'translateX(' + x.toFixed(2) + 'px)';
      say.classList.toggle('on', !reduced && elapsed > dur * .3 && elapsed < dur * .3 + 1600);
      raf = requestAnimationFrame(tick);
    }
    el.style.transform = 'translateX(' + (reduced ? W - w : W) + 'px)';
    raf = requestAnimationFrame(tick);
  }
  document.addEventListener('click', function (event) {
    if (event.target instanceof Element && event.target.closest('[data-crapaud]')) start();
  });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden && stop) stop();
  });
  window.addEventListener('pagehide', function () { if (stop) stop(); });
})();
